import datetime
import os
import time
import zipfile

from taf.gnb.oam.coam.cu.exception import NegativeApiResponse, TimeoutException

POLLING_INTERVAL = 1


def save_snapshot(instance, start_time, operation_id, operation_timeout, directory, compressed, request_timeout=30):
    """
    Waits until snapshot collection operation either succeeds or fails.
    If it succeeds, the snapshot is saved either to one zip file if compressed=True
    or into separate files if compressed=False.

    If saving fails the operation is deleted before raising error not to cause conflict for next execution.

    :param instance: instance on which methods will be called
    :param start_time: time when snapshot collection was triggered
    :param operation_id: ID of snapshot collection operation
    :param operation_timeout: timeout for whole snapshot collection operation
    :param directory: directory where snapshot will be saved
    :param compressed: True if snapshot should be saved to zip file otherwise False
    :param request_timeout: timeout for a single request

    :return: path where snapshot was saved
    :rtype: str
    """
    files = _poll_snapshot_collection_status(instance=instance,
                                             operation_id=operation_id,
                                             start_time=start_time,
                                             operation_timeout=operation_timeout)

    try:
        snapshot_path = _save_snapshot_and_return_path(instance=instance,
                                                       directory=directory,
                                                       compressed=compressed,
                                                       files=files,
                                                       operation_id=operation_id,
                                                       request_timeout=request_timeout)

    except Exception as e:
        instance.local_client.delete_snapshot_operation(operation_id=operation_id)
        raise e

    return snapshot_path


def teardown_for_snapshot_collection(instance, start_time, operation_id, request_timeout, operation_timeout):
    """
    Teardown method for snapshot collection operation.
    Deletes snapshot collection operation with given operation_id and checks if snapshot status changes
    to "idle" within operation_timeout.

    :param instance: instance on which methods will be called
    :param start_time: time when snapshot collection was triggered
    :param operation_id: ID of snapshot collection operation
    :param request_timeout: timeout for a single request
    :param operation_timeout: timeout for an entire operation

    :raises: TimeoutException if operation timed out
    """
    instance.local_client.delete_snapshot_operation(operation_id=operation_id)

    stop_time = start_time + operation_timeout
    while time.time() < stop_time:
        snapshot_status = instance.local_client.check_snapshot_status(timeout=request_timeout)
        if snapshot_status['status'] == 'idle':
            return

        time.sleep(POLLING_INTERVAL)

    raise TimeoutException(f"Snapshot operation timeout: {operation_timeout} exceeded.")


def _poll_snapshot_collection_status(instance, operation_id, start_time, operation_timeout):
    stop_time = start_time + operation_timeout
    while time.time() < stop_time:
        response = instance.local_client.get_snapshot_operation(operation_id=operation_id)
        status = response['status']

        if status == 'failed':
            instance.local_client.delete_snapshot_operation(operation_id=operation_id)
            raise NegativeApiResponse(f"Snapshot operation failed with: {response['failureInfo']}")

        if status == 'succeeded':
            return response["files"]

        time.sleep(POLLING_INTERVAL)

    raise TimeoutException(f"Snapshot operation timeout: {operation_timeout} exceeded.")


def _save_snapshot_and_return_path(instance, compressed, files, directory, operation_id, request_timeout):
    if compressed:
        snapshot_file_path = os.path.join(directory, f"Snapshot_{datetime.datetime.now().strftime('%Y%m%d-%H%M%S')}.zip")
        os.makedirs(os.path.dirname(snapshot_file_path), exist_ok=True)

        _save_all_snapshot_files_to_zip(instance=instance,
                                        snapshot_files=files,
                                        snapshot_file_path=snapshot_file_path,
                                        operation_id=operation_id,
                                        request_timeout=request_timeout)

        return snapshot_file_path

    else:
        for file in files:
            _save_snapshot_file(instance=instance,
                                directory=directory,
                                operation_id=operation_id,
                                file_id=file['fileId'],
                                request_timeout=request_timeout)

        return directory


def _save_all_snapshot_files_to_zip(instance, snapshot_files, snapshot_file_path, operation_id, request_timeout):
    snapshot_zip = zipfile.ZipFile(snapshot_file_path, 'w', zipfile.ZIP_DEFLATED)
    for f in snapshot_files:
        snapshot_file_content = instance.local_client.get_snapshot_file(operation_id=operation_id,
                                                                        file_id=f['fileId'],
                                                                        timeout=request_timeout)
        snapshot_zip.writestr(zinfo_or_arcname=f['fileId'],
                              data=snapshot_file_content)

    snapshot_zip.close()


def _save_snapshot_file(instance, directory, operation_id, file_id, request_timeout):
    snapshot_file = instance.local_client.get_snapshot_file(operation_id=operation_id,
                                                            file_id=file_id,
                                                            timeout=request_timeout)
    filepath = os.path.join(directory, file_id)
    with open(filepath, 'wb+') as f:
        f.write(snapshot_file)
